// Right-panel views: "Discoveries" (headline new candidates, generated by `python -m pipeline discoveries`)
// and "Southern Africa" (what the data says about local places). All numbers come from the JSON files, so
// the text stays in step with the published data.
import type { Dataset } from '../data';
import type { Discovery, FactorRow, SpotlightFile } from '../types';
import { esc, fmtLatLon } from '../format';

export interface PanelHooks {
  flyToDiscovery(d: Discovery): void;
  copyDiscovery(d: Discovery): void;
  showRegion(id: 'safrica'): void;
  flyToPlace(targetId: string, lat: number, lon: number): void;
}

const short = (name: string) => name.replace(/^(Moon|Mars) – /, '');
const fmt = (v: number, unit: string) => {
  const a = Math.abs(v);
  const s = a >= 100 ? v.toFixed(0) : a >= 10 ? v.toFixed(1) : a >= 1 ? v.toFixed(2) : v.toFixed(3);
  if (unit === 'fraction') return `${(v * 100).toFixed(0)}%`;
  return `${s.replace(/\.?0+$/, '') || '0'}${unit ? (unit === '%' ? '%' : ` ${unit}`) : ''}`;
};
const topPct = (p: number) => `top ${Math.max(0.01, 100 - p).toFixed(100 - p < 1 ? 2 : 1)}%`;

function factor(r: FactorRow): string {
  const flag = r.synthetic ? ' <span class="badge synth">placeholder</span>' : r.proxy ? ' <span class="badge proxy">proxy</span>' : '';
  const tgt = r.target_raw === null ? 'beyond Earth' : r.beyond_earth ? `${fmt(r.target_raw, r.unit)} (Earth max/min ${fmt(r.target, r.unit)})` : fmt(r.target, r.unit);
  return `<li><b>${esc(r.name)}</b> ${fmt(r.site, r.unit)} <span class="vs">vs ${tgt}</span>${flag}</li>`;
}

export function renderDiscoveries(el: HTMLElement, ds: Dataset, hooks: PanelHooks) {
  const file = ds.discoveries;
  if (!file || !file.discoveries.length) {
    el.innerHTML = '<p class="note">No discoveries file in this build. Run <code>python -m pipeline discoveries</code>.</p>';
    return;
  }
  const cards = file.discoveries
    .map(
      (d, k) => `<article class="disc" data-k="${k}">
      <div class="disc-head">
        <div><div class="eyebrow">${esc(short(d.target_name))}</div><h3>${esc(d.name)}</h3>
        <div class="note">${esc(d.country)} · ${fmtLatLon(d.lat, d.lon)}</div></div>
        <div class="disc-score"><b>${(d.score * 100).toFixed(1)}</b><span>${topPct(d.percentile)}</span></div>
      </div>
      <p class="disc-new">${d.novelty_km.toLocaleString()} km from the nearest known analog (${esc(d.nearest_known_analog)}).</p>
      ${d.literature ? `<p class="note disc-lit">Not on our list, but ${esc(d.literature.replace(/^Already proposed/, 'already proposed'))} Our method found it independently.</p>` : ''}
      <div class="disc-cols">
        <div><h4>Closest match</h4><ul>${d.best.map(factor).join('')}</ul></div>
        <div><h4>Biggest gaps</h4><ul>${d.worst.map(factor).join('')}</ul></div>
      </div>
      <p><b>Could be used for:</b> ${esc(d.uses)}</p>
      <details><summary>Caveats</summary><ul class="caveats">${d.caveats.map((c) => `<li>${esc(c)}</li>`).join('')}</ul></details>
      <div class="disc-actions"><button class="btn" data-act="fly">Fly there</button><button class="text-btn" data-act="copy">Copy link</button></div>
    </article>`,
    )
    .join('');
  el.innerHTML = `<p class="note">New candidates the scoring itself picked: Earth's top 1% for a target and at least 500 km from every known analog. Rule: ${esc(file.rule)}</p>${cards}`;
  el.querySelectorAll<HTMLElement>('.disc').forEach((card) => {
    const d = file.discoveries[+card.dataset.k!];
    card.querySelector<HTMLButtonElement>('[data-act=fly]')!.onclick = () => hooks.flyToDiscovery(d);
    card.querySelector<HTMLButtonElement>('[data-act=copy]')!.onclick = () => hooks.copyDiscovery(d);
  });
}

function placeSentence(p: SpotlightFile['places'][number]): string {
  const best = p.results.find((r) => r.target === p.best_target)!;
  const mars = p.results.filter((r) => r.target.startsWith('mars_')).sort((a, b) => b.percentile - a.percentile)[0];
  const worst = best.worst.map((w) => `${w.name.toLowerCase()} (${fmt(w.site, w.unit)} here)`).join(' and ');
  const strong = best.percentile >= 99 ? 'a top-1% match' : best.percentile >= 95 ? 'a strong match' : best.percentile >= 85 ? 'a moderate match' : 'a weak match';
  let s = `Best fit: <b>${esc(short(best.target_name))}</b>, ${strong} (${topPct(best.percentile)} of Earth's land).`;
  if (mars && mars.target !== best.target) s += ` For Mars, ${esc(short(mars.target_name))} is ${topPct(mars.percentile)}.`;
  s += ` Held back by ${esc(worst)}.`;
  return s;
}

export function renderSpotlight(el: HTMLElement, ds: Dataset, hooks: PanelHooks) {
  const sp = ds.spotlight;
  if (!sp) {
    el.innerHTML = '<p class="note">No spotlight file in this build. Run <code>python -m pipeline discoveries</code>.</p>';
    return;
  }
  const basaltSynth = sp.synthetic_features.includes('basalt');
  const rows = sp.places
    .map(
      (p, k) => `<article class="spot" data-k="${k}">
      <h3>${esc(p.name)}</h3>
      <p class="note">${esc(p.why)}</p>
      <p>${placeSentence(p)}</p>
      <div class="spot-bars">${p.results
        .map((r) => `<button class="spot-bar" data-t="${r.target}" title="${esc(r.target_name)}: ${topPct(r.percentile)} · fly there"><span>${esc(short(r.target_name).replace(/ \(.*\)$/, ''))}</span><i style="width:${Math.max(2, r.percentile).toFixed(0)}%"></i><em>p${r.percentile.toFixed(r.percentile >= 99 ? 1 : 0)}</em></button>`)
        .join('')}</div>
    </article>`,
    )
    .join('');
  const rb = [...sp.region_best].sort((a, b) => b.percentile - a.percentile)[0];
  el.innerHTML = `
    <p>What our scoring finds in southern Africa. This is reported as the data says it, including the places that score poorly.</p>
    <button class="btn" id="sa-region">Show the southern Africa map</button>
    <p class="note">The region's single best cell is at ${fmtLatLon(rb.lat, rb.lon)} (${esc(rb.country)}) for ${esc(short(rb.target_name))}, ${topPct(rb.percentile)} of Earth's land.</p>
    ${basaltSynth ? '<div class="warn-box">The basalt layer is still a placeholder, so the Karoo dolerites and the lava-tube scores do not yet reflect real geology.</div>' : ''}
    ${rows}
    <p class="note">${esc(sp.method)}</p>
    <p class="note"><b>Why Vredefort scores low:</b> no global layer records impact structures, and at ~2 billion years old the crater is deeply eroded and now sits in farmland with ~500 mm of rain a year. Its value is impact geology (shocked rock, shatter cones), which an 11 km climate-and-terrain score cannot see.</p>`;
  el.querySelector<HTMLButtonElement>('#sa-region')!.onclick = () => hooks.showRegion('safrica');
  el.querySelectorAll<HTMLElement>('.spot').forEach((card) => {
    const p = sp.places[+card.dataset.k!];
    card.querySelectorAll<HTMLButtonElement>('.spot-bar').forEach((b) => {
      const r = p.results.find((x) => x.target === b.dataset.t)!;
      b.onclick = () => hooks.flyToPlace(r.target, r.lat, r.lon);
    });
  });
}
